1) Display employees having salary is equal to 3897.43.
select * from employees where salary=3897.43;
2) Display employees having salary less than 4000 and hiring year greater than 1990.
select * from employees where salary < 4000 and to_char(HIRE_DATE,'YYYY')>1990;
3) Display all employees in IT or Accounting department.
it will display all details
select * from employees inner join departments on employees.department_id=departments.department_id where departments.department_name in ('IT','Accounting');
it will display only emp_id,first name, dep name
select E.EMPLOYEE_ID,e.first_name,d.department_name from employees e inner join departments d on e.department_id=d.department_id where d.department_name in ('IT','Accounting');
4) How to display employees whose salary between 2500 and 5000 without using between operators?
select * from employees where salary>=2500 and salary<=5000;
5) Display employees whose COMMISION_PCT is other than 0.10.
select * from employees where COMMISSION_PCT!=0.10;
select * from employees where COMMISSION_PCT not in 0.10;
select first_name, last_name,commission_pct from employees where COMMISSION_PCT!=0.10;
6) Delete employees from department Purchasing and salary less than 2500.
delete from employees E where employee_id in (select e.employee_id from employees E inner join departments d on e.department_id=d.department_id where d.department_name = 'Purchasing' and e.salary < 50000);
7) Display first name last name and salary of an employee who is having max salary.
select first_name, last_name, salary from employees where salary=(select max(salary)from employees);
8) What is the Query to fetch last record from the employees table?
--1st Method
select employees.* from employees where rowid = (select max(rowid) from employees);
--2nd Method
select * from (select employees.*,rownum r from employees) where r=(select max(rownum) from employees);
9) What is the Query to fetch first record from Employee table?
--1st approach
select * from employees where rowid = (select min (rowid) from employees);
--2nd approach
select * from employees where rownum = 1;
10) What is Query to display last 5 Records from Employee table?
--1st approach
select * from (select employees.*, dense_rank() over (order by (rownum) desc) as drank from employees) where drank between 1 and 5;
--2nd approach
select * from (select rownum as extrarow, employees.* from employees) where extrarow > (select count(*)-5 from employees);
